// atep.dev copy: h() and s() assign style.cssText instead of setAttribute("style") so the page runs under CSP (generated by site/build-demo.mjs).
// ATEP-R demo UI: plain DOM and SVG. All protocol work happens in engine.mjs
// (real @atep/core); this file only draws and wires controls.

import { Engine, UNITS, ATTACKER, MAP, CLASS_TABLE, SCRIPT_LENGTH, T0, TICK_SECS, shortClaim } from "./engine.mjs";

const $ = (s) => document.querySelector(s);
const SVGNS = "http://www.w3.org/2000/svg";
const reduceMq = window.matchMedia("(prefers-reduced-motion: reduce)");
const BASE_TICK_MS = 2400;
const FLIGHT_MS = 1300;
const NOT_DELIVERED_REACH = 0.45; // an envelope to or from the offline controller stops part of the way

let engine = null;
let playing = false;
let speed = 1;
let tickTimer = null;
let selected = null;
let flights = [];
let raf = 0;
let busy = false;
let policyKey = "";

// ------------------------------------------------------------------ helpers
function h(tag, attrs = {}, ...kids) {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v === false || v == null) continue;
    if (k === "class") e.className = v;
    else if (k === "text") e.textContent = v;
    else if (k === "style") e.style.cssText = v;
    else e.setAttribute(k, v === true ? "" : v);
  }
  for (const c of kids.flat()) if (c != null) e.append(c.nodeType ? c : document.createTextNode(String(c)));
  return e;
}
function s(tag, attrs = {}, ...kids) {
  const e = document.createElementNS(SVGNS, tag);
  for (const [k, v] of Object.entries(attrs)) if (v != null) { if (k === "style") e.style.cssText = v; else e.setAttribute(k, v); }
  for (const c of kids.flat()) if (c != null) e.append(c.nodeType ? c : document.createTextNode(String(c)));
  return e;
}
const kb = (n) => (n / 1024).toFixed(1) + " KB";
const reduce = () => reduceMq.matches;

function shapePath(shape, r) {
  if (shape === "diamond") return `M0 ${-r * 1.15} L${r * 1.15} 0 L0 ${r * 1.15} L${-r * 1.15} 0 Z`;
  if (shape === "triangle") return `M0 ${-r * 1.15} L${r * 1.1} ${r * 0.85} L${-r * 1.1} ${r * 0.85} Z`;
  if (shape === "hexagon") return `M${r * 1.1} 0 L${r * 0.55} ${r * 0.95} L${-r * 0.55} ${r * 0.95} L${-r * 1.1} 0 L${-r * 0.55} ${-r * 0.95} L${r * 0.55} ${-r * 0.95} Z`;
  if (shape === "square") return `M${-r * 0.9} ${-r * 0.9} h${r * 1.8} v${r * 1.8} h${-r * 1.8} Z`;
  return `M${-r} 0 a${r} ${r} 0 1 0 ${2 * r} 0 a${r} ${r} 0 1 0 ${-2 * r} 0 Z`;
}
function glyphSvg(p) {
  const svg = s("svg", { class: "glyph", viewBox: "-6 -6 12 12", "aria-hidden": "true" });
  svg.append(s("path", { d: shapePath(p.shape, 4.6), fill: p.color, stroke: "#04090d", "stroke-width": "0.6" }));
  return svg;
}
const party = (id) => (id === "x" ? ATTACKER : UNITS.find((u) => u.id === id));
const whoLabel = (id) => {
  const p = party(id);
  return h("span", { class: "who" }, glyphSvg(p), " ", p.n ? `${p.n} ${p.role}` : p.name);
};
const whoText = (id) => {
  const p = party(id);
  return p.n ? `Unit ${p.n} (${p.role})` : p.name;
};

// ---------------------------------------------------------------------- map
const map = $("#map");
const unitEls = {};
let flightLayer;
let badgeLayer;

function buildMap() {
  map.replaceChildren();
  const defs = s("defs", {},
    s("pattern", { id: "hatch", width: "2", height: "2", patternUnits: "userSpaceOnUse", patternTransform: "rotate(45)" },
      s("rect", { width: "2", height: "2", fill: "#2a0f12" }),
      s("line", { x1: "0", y1: "0", x2: "0", y2: "2", stroke: "#a33a44", "stroke-width": "0.5" })));
  map.append(defs);
  map.append(s("rect", { x: 0, y: 0, width: MAP.w, height: MAP.h, fill: "#070d13" }));
  for (let x = 10; x < MAP.w; x += 10) map.append(s("line", { x1: x, y1: 0, x2: x, y2: MAP.h, stroke: "#13202c", "stroke-width": "0.2" }));
  for (let y = 10; y < MAP.h; y += 10) map.append(s("line", { x1: 0, y1: y, x2: MAP.w, y2: y, stroke: "#13202c", "stroke-width": "0.2" }));
  const hz = MAP.hazard;
  map.append(s("rect", { x: hz.x, y: hz.y, width: hz.w, height: hz.h, fill: "url(#hatch)", stroke: "#d4505c", "stroke-width": "0.4", "stroke-dasharray": "1.2 0.8" }));
  map.append(s("text", { class: "hazard-label", x: hz.x + hz.w / 2, y: hz.y + hz.h / 2 + 0.7 }, "KEEP-OUT"));
  map.append(s("text", { x: 1.5, y: 3.4, "font-size": "2", fill: "#5d7488", style: "fill:#5d7488" }, "Simulated map (abstract units)"));

  // intruder, faint until it attacks
  const ix = s("g", { id: "g-x", transform: "translate(8 52)", opacity: "0.45" });
  ix.append(s("path", { d: shapePath("square", 2.6), fill: "none", stroke: ATTACKER.color, "stroke-width": "0.5", "stroke-dasharray": "0.8 0.6" }));
  ix.append(s("text", { class: "lbl", y: 6, style: "font-size:1.9px;text-anchor:middle" }, "Intruder"));
  map.append(ix);

  const targetLayer = s("g");
  map.append(targetLayer);
  for (const u of UNITS) {
    const g = s("g", { class: "unit", id: "g-" + u.id });
    const tgt = s("g", { id: "t-" + u.id, class: "unit", opacity: "0.7" });
    tgt.append(s("path", { d: "M-1 -1 L1 1 M1 -1 L-1 1", stroke: u.color, "stroke-width": "0.5", fill: "none" }));
    targetLayer.append(tgt);
    g.append(s("path", { class: "shape", d: shapePath(u.shape, 2.8), fill: u.color, stroke: "#04090d", "stroke-width": "0.5" }));
    g.append(s("text", { class: "num" }, String(u.n)));
    g.append(s("text", { class: "lbl", y: 6.2 }, `${u.n} ${u.role.replace(" (to be revoked)", "")}`));
    g.append(s("text", { class: "rev", y: 8.4, id: "rev-" + u.id }, ""));
    map.append(g);
    unitEls[u.id] = { g, tgt };
  }
  badgeLayer = s("g");
  flightLayer = s("g");
  map.append(badgeLayer, flightLayer);
}

function placeUnits(instant) {
  for (const u of engine.units) {
    const el = unitEls[u.id];
    const dur = reduce() || instant ? "0s" : `${(BASE_TICK_MS / 1000 / speed).toFixed(2)}s`;
    for (const e of [el.g, el.tgt]) e.style.transitionDuration = dur;
    el.g.style.transform = `translate(${u.pos.x}px, ${u.pos.y}px)`;
    el.tgt.style.transform = `translate(${u.target.x}px, ${u.target.y}px)`;
    el.tgt.style.display = u.status === "revoked" ? "none" : "";
    el.g.classList.toggle("revoked", u.status === "revoked");
    el.g.querySelector(".shape").setAttribute("fill", u.status === "revoked" ? "#59636d" : u.color);
    const off = u.status === "offline";
    el.g.classList.toggle("offline", off);
    el.g.querySelector(".shape").setAttribute("stroke-dasharray", u.status === "revoked" || off ? "1 0.7" : "");
    const tag = $("#rev-" + u.id);
    tag.textContent = u.status === "revoked" ? "REVOKED, LOCKED OUT" : off ? "CONTROLLER OFFLINE" : u.mode === "e-stopped" ? "E-STOPPED" : "";
    tag.classList.toggle("note", u.status !== "revoked");
  }
}

function posOf(id) {
  if (id === "x") return { x: 8, y: 52 };
  return engine.u(id).pos;
}

// ------------------------------------------------------------------ flights
function envGlyph(rec) {
  const col = party(rec.from).color;
  const g = s("g", { class: "flight", tabindex: "0", role: "button", "aria-label": `Envelope ${rec.id}, ${rec.cls}, ${whoText(rec.from)} to ${whoText(rec.to)}, ${rec.size} bytes of ciphertext. Press Enter to inspect.` });
  g.append(s("rect", { x: -6.5, y: -3.2, width: 13, height: 6.4, rx: 1, fill: "#0b1620", stroke: col, "stroke-width": "0.5" }));
  // padlock
  g.append(s("rect", { x: -5.4, y: -0.6, width: 2.4, height: 1.9, rx: 0.3, fill: col }));
  g.append(s("path", { d: "M-4.9 -0.6 v-0.7 a0.7 0.7 0 0 1 1.4 0 v0.7", stroke: col, "stroke-width": "0.35", fill: "none" }));
  g.append(s("text", { x: -2.2, y: -0.9 }, kb(rec.size)));
  g.append(s("text", { class: "hex", x: -5.6, y: 2.6 }, rec.preview.slice(0, 20)));
  g.addEventListener("click", () => select(rec));
  g.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      select(rec);
    }
  });
  return g;
}

function launch(rec, delayMs) {
  const a = posOf(rec.from);
  const b = posOf(rec.to);
  const col = party(rec.from).color;
  const nd = rec.delivered === false;
  const line = s("line", { x1: a.x, y1: a.y, x2: b.x, y2: b.y, stroke: nd ? "#8aa0b3" : col, "stroke-width": "0.3", "stroke-dasharray": nd ? "0.4 1.6" : "1 1", opacity: nd ? "0.5" : "0.6" });
  const g = envGlyph(rec);
  flightLayer.append(line, g);
  const f = { rec, a: { ...a }, b: { ...b }, line, g, start: performance.now() + delayMs / speed, dur: FLIGHT_MS / speed, done: false };
  g.style.display = "none";
  line.style.display = "none";
  flights.push(f);
  if (!raf) raf = requestAnimationFrame(frame);
}

function frame(now) {
  raf = 0;
  for (const f of flights) {
    if (f.done) continue;
    if (now < f.start) continue;
    f.g.style.display = "";
    f.line.style.display = "";
    const t = Math.min(1, (now - f.start) / f.dur);
    const e = (reduce() ? 0.5 : t) * (f.rec.delivered === false ? NOT_DELIVERED_REACH : 1);
    const x = f.a.x + (f.b.x - f.a.x) * e;
    const y = f.a.y + (f.b.y - f.a.y) * e - 3.6;
    f.g.setAttribute("transform", `translate(${x} ${y})`);
    if (t >= 1) arrive(f);
  }
  flights = flights.filter((f) => !f.done);
  if (flights.length) raf = requestAnimationFrame(frame);
}

function arrive(f) {
  f.done = true;
  const rec = f.rec;
  f.g.remove();
  f.line.remove();
  appendLog(rec);
  const nd = rec.delivered === false;
  const src = posOf(rec.from);
  const full = posOf(rec.to);
  const dst = nd ? { x: src.x + (full.x - src.x) * NOT_DELIVERED_REACH, y: src.y + (full.y - src.y) * NOT_DELIVERED_REACH } : full;
  const bad = rec.ok === false;
  const text = nd ? "NOT DELIVERED: controller offline" : bad ? `REJECTED step ${rec.step} ${rec.error}` : rec.warnings.length ? "VERIFIED (warning)" : "VERIFIED";
  const bx = Math.min(Math.max(dst.x, 24), MAP.w - 24);
  const b = s("g", { transform: `translate(${bx} ${dst.y - 5.2})` });
  b.append(s("text", { class: "badge " + (nd ? "badge-nd" : bad ? "badge-bad" : "badge-ok") }, (nd ? "" : bad ? "✗ " : "✓ ") + text));
  badgeLayer.append(b);
  setTimeout(() => b.remove(), 2600 / speed + 600);
  if (bad) {
    const el = unitEls[rec.to]?.g;
    if (el && !reduce()) {
      el.classList.add("flash-bad");
      setTimeout(() => el.classList.remove("flash-bad"), 1900);
    }
  }
  banner(rec);
  if (!selected || rec.kind === "attack" || rec.ok === false) select(rec, true);
}

function banner(rec) {
  const el = $("#banner");
  const route = `${whoText(rec.from)} to ${whoText(rec.to)}`;
  if (rec.delivered === false) {
    el.className = "banner nd";
    el.textContent = `${rec.cls} message, ${route}: not delivered, controller offline. This is not a verification failure: the envelope never reached a verifier.`;
  } else if (rec.ok) {
    el.className = "banner ok";
    el.textContent = `${rec.cls} command, ${route}: verified. ${rec.effect}.` + (rec.warnings.length ? " Warning: " + rec.warnings[0] : "");
  } else if (rec.staleCaused) {
    el.className = "banner bad";
    el.textContent = `${rec.cls} command, ${route}, REJECTED at step ${rec.step} (${rec.error}). Fails closed: the root revocation list is stale, and the same envelope verifies with a fresh one. The receiver ignores it and continues its last safe behavior.`;
  } else {
    el.className = "banner bad";
    el.textContent = `${rec.attack ? "ATTACK " + rec.attack + ": " : ""}${rec.cls} command, ${route}, REJECTED at step ${rec.step} (${rec.error}). Receiver ignores it and ${rec.attack ? "carries on" : "continues its last safe behavior"}.`;
  }
}

// ---------------------------------------------------------------------- log
const logBody = $("#log-body");
let rowEls = new Map();

function resultCell(rec) {
  if (rec.delivered === false) return h("span", { class: "res-nd" }, "NOT DELIVERED: controller offline");
  if (rec.ok) return h("span", { class: rec.warnings.length ? "res-warn" : "res-ok" }, rec.warnings.length ? "VERIFIED with warning" : "VERIFIED");
  return h("span", { class: "res-bad" }, `REJECTED at step ${rec.step}: ${rec.error}`);
}

function appendLog(rec) {
  const tr = h("tr", { class: rec.delivered === false ? "nd" : rec.ok ? "" : "rej" });
  const cell = (label, ...kids) => h("td", { "data-label": label }, ...kids);
  tr.append(
    cell("Envelope", h("button", { type: "button", class: "selbtn", "aria-label": `Inspect envelope ${rec.id}` }, rec.id)),
    cell("Time", `t+${rec.now - T0} s`),
    cell("Kind", rec.attack ? h("span", { class: "pill attack" }, "attack: " + rec.attack) : h("span", { class: "pill" }, "fleet traffic"), rec.tag ? h("span", { class: "pill tag" }, rec.tag) : null),
    cell("Class", h("span", { class: "pill" }, rec.cls)),
    cell("From", whoLabel(rec.from)),
    cell("To", whoLabel(rec.to)),
    cell("Size", `${rec.size.toLocaleString("en-US")} B (${kb(rec.size)})`),
    cell("Result", resultCell(rec)),
    cell("Outcome", rec.effect + (rec.replayOf ? ` (replay of ${rec.replayOf})` : "") + (rec.tamperedAt != null ? ` (byte ${rec.tamperedAt} flipped)` : "")),
  );
  tr.addEventListener("click", () => select(rec));
  // Newest first: stay pinned to the newest row unless the reader has scrolled down.
  const wrap = logBody.closest(".tablewrap");
  const pinned = wrap.scrollTop < 8;
  logBody.prepend(tr);
  if (pinned) wrap.scrollTop = 0;
  rowEls.set(rec.id, tr);
  $("#log-count").textContent = String(engine.log.length);
}

// ---------------------------------------------------------------- inspector
function revealRow(rec) {
  const tr = rowEls.get(rec.id);
  const wrap = logBody.closest(".tablewrap");
  if (!tr || !wrap) return;
  const r = tr.getBoundingClientRect();
  const w = wrap.getBoundingClientRect();
  if (r.top < w.top) wrap.scrollTop -= w.top - r.top;
  else if (r.bottom > w.bottom) wrap.scrollTop += r.bottom - w.bottom;
}

function select(rec, quiet) {
  selected = rec;
  for (const [id, tr] of rowEls) tr.classList.toggle("sel", id === rec.id);
  if (!quiet && document.body.classList.contains("log-side")) revealRow(rec);
  const box = $("#inspect-sel");
  box.replaceChildren(
    h("div", {}, h("strong", {}, rec.id), ` | ${rec.cls} | `, whoLabel(rec.from), " to ", whoLabel(rec.to), ` | ${rec.size.toLocaleString("en-US")} bytes`),
    h("div", { class: "mono" }, `ciphertext: ${rec.preview.match(/.{1,8}/g).join(" ")} ...`),
    h("details", {}, h("summary", {}, "Show the first 256 bytes as seen on the wire"), h("pre", {}, hexDump(rec.bytes, 256))),
  );
  $("#btn-decrypt").disabled = false;
  $("#btn-observer").disabled = false;
  $("#btn-decrypt").textContent = `Decrypt as recipient (${party(rec.to).name})`;
  if (!quiet) $("#inspect-out").replaceChildren();
}

function hexDump(bytes, n) {
  const out = [];
  for (let i = 0; i < Math.min(n, bytes.length); i += 16) {
    const row = Array.from(bytes.slice(i, i + 16), (b) => b.toString(16).padStart(2, "0")).join(" ");
    out.push(i.toString(16).padStart(4, "0") + "  " + row);
  }
  return out.join("\n");
}

function nameFor(id) {
  return engine.nameOf.get(id) ?? id.slice(0, 16) + "...";
}

function claimsList(claims) {
  if (!claims.length) return h("p", {}, "No claims were required for this check.");
  return h("ul", { class: "chain" }, claims.map((c) =>
    h("li", {}, h("strong", {}, shortClaim(c.claim)), ` issued by ${nameFor(c.issuer)}, anchored at root ${nameFor(c.root)}; chain: `,
      c.chain.map((l) => `${shortClaim(l.claim)} (${nameFor(l.issuer)} to ${nameFor(l.subject)})`).join(" > "))));
}

$("#btn-decrypt").addEventListener("click", () => {
  if (!selected) return;
  const out = $("#inspect-out");
  const r = engine.openAsRecipient(selected);
  out.replaceChildren();
  if (!r.ok) {
    out.append(h("div", { class: "head bad" }, `${r.who}: decryption FAILED`), h("pre", {}, r.error));
    return;
  }
  out.append(
    h("div", { class: "head good" }, `${r.who} decrypted this envelope with its own keys (${r.innerSize.toLocaleString("en-US")} bytes of signed envelope)`),
    h("div", {}, `Signed by ${r.signerName}, command class "${r.commandClass}". Plaintext command:`),
    h("pre", {}, JSON.stringify(r.payload, null, 2)),
  );
  if (!r.verify) {
    out.append(h("div", { class: "head" }, "Not delivered: the controller was offline, so no verifier ran on this envelope."));
  } else if (r.verify.ok) {
    out.append(h("div", { class: "head good" }, "Real verifier result: VERIFIED. Claims chain:"), claimsList(r.verify.claims));
    if (r.verify.warnings?.length) out.append(h("div", { class: "warnc" }, "Warning: " + r.verify.warnings.join("; ")));
  } else {
    out.append(h("div", { class: "head bad" }, `Real verifier result: REJECTED at step ${r.verify.step} (${r.verify.error}). The receiver did not act on this command.`));
  }
});

$("#btn-observer").addEventListener("click", () => {
  if (!selected) return;
  const out = $("#inspect-out");
  const r = engine.openAsObserver(selected);
  out.replaceChildren(
    h("div", { class: "head " + (r.ok ? "good" : "bad") }, r.ok ? "Observer decrypted the envelope (unexpected)" : `${r.who}: decryption FAILED`),
    h("pre", {}, r.error ?? "decrypted"),
    h("div", {}, `Real verifier run by the observer: ${r.verify.ok ? "accepted" : `rejected at step ${r.verify.step} (${r.verify.error})`}. The observer holds no X25519 or ML-KEM key that matches the recipient, so the ciphertext stays unreadable. Relays and brokers on the path are in the same position.`),
  );
});

// --------------------------------------------------------------- attacks
const ATTACK_TEXT = {
  replay: "Replay: a previously accepted envelope is delivered again to the same receiver.",
  tamper: "Tamper: one byte of an honest envelope is flipped in transit.",
  forged: "Forgery: an identity with no attestations signs a motion command.",
  noclaim: "Missing claim: a real fleet member presents no peer-motion delegation and sends a motion command.",
};
document.querySelectorAll("[data-attack]").forEach((b) =>
  b.addEventListener("click", () => {
    if (!engine || busy) return;
    const name = b.dataset.attack;
    let rec;
    try {
      rec = engine.attack(name);
    } catch (e) {
      $("#attack-out").textContent = "Run the demo for a few ticks first: " + e.message + ".";
      return;
    }
    $("#attack-out").replaceChildren(
      ATTACK_TEXT[name] + " Result from the real verifier: ",
      h("strong", { class: rec.ok ? "bad" : "good" }, rec.ok ? "ACCEPTED (this would be a bug)" : `REJECTED at step ${rec.step}, error ${rec.error}`),
      ".",
    );
    launch(rec, 0);
    refreshPolicy();
  }),
);

// ----------------------------------------------------------- policy panel
function refreshPolicy(force) {
  const key = `${engine.srls.root.sequence}|${engine.stale}|${engine.revoked}|${engine.controllerOffline}|${!!engine.pendingRevoke}`;
  if (!force && key === policyKey) return;
  policyKey = key;
  const root = $("#policy");
  const tp = engine.trustPolicy();
  const wrap = h("div", { class: "pol-grid two" });

  const left = h("div", {});
  left.append(
    h("h3", {}, "Policy every unit enforces"),
    h("ul", { class: "chain" },
      h("li", {}, "Trusted roots: ", `${engine.parties.root.name} (${tp.roots[0].slice(0, 20)}...), ${engine.parties.cert.name} (${tp.roots[1].slice(0, 20)}...)`),
      h("li", {}, "ATEP-R enforcement: on (encryption required, command class required, claims per class)"),
      h("li", {}, "Revocation lists: stale or missing means fail closed for motion and actuation; telemetry may continue"),
      h("li", {}, "Replay protection: per receiver nonce set. Clock skew allowed: 300 s"),
      h("li", {}, "Caches: every unit holds the root, certifier and controller keys and the revocation lists it saved earlier, so checking a peer needs no contact with the controller"),
      h("li", {}, `Controller reachable now: ${engine.controllerOffline ? "NO (units use the lists they already hold)" : "yes"}`),
    ),
    h("details", {}, h("summary", {}, "Raw policy object passed to the verifier"), h("pre", {}, JSON.stringify(tp, null, 2))),
  );
  const ct = h("table", {}, h("caption", { class: "sr" }, "Command class minimum claims"),
    h("thead", {}, h("tr", {}, ["Class", "Minimum claims on the sender", "Stale or missing SRL"].map((t) => h("th", { scope: "col" }, t)))),
    h("tbody", {}, CLASS_TABLE.map((r) => h("tr", {}, h("td", { "data-label": "Class" }, r.cls), h("td", { "data-label": "Minimum claims" }, r.minimum), h("td", { "data-label": "Stale SRL", class: r.stale.includes("CLOSED") ? "res-bad" : "res-warn" }, r.stale)))));
  left.append(h("h3", {}, "Command classes (spec section 17)"), ct);

  const srlRows = [["root", "Fleet operator (root)"], ["u1", "Unit 1 (controller)"], ["cert", "Safety certifier"]].map(([k, n]) => {
    const x = engine.srls[k];
    const stale = x.stale;
    return h("tr", {},
      h("td", { "data-label": "Issuer" }, n),
      h("td", { "data-label": "Sequence" }, String(x.sequence)),
      h("td", { "data-label": "Next update" }, `t${x.nextUpdate - T0 >= 0 ? "+" : ""}${x.nextUpdate - T0} s`),
      h("td", { "data-label": "Status", class: stale ? "res-bad" : "res-ok" }, stale ? "STALE (past next-update)" : "fresh"),
      h("td", { "data-label": "Revoked" }, x.revoked.length ? x.revoked.map((r) => `${nameFor(r.id)} (compromised, from t+${r.at - T0} s)`).join("; ") : "none"));
  });
  if (engine.pendingRevoke) left.append(h("p", { class: "attack-out" }, "Pending: the operator signed a revocation naming Unit 3, but it reaches units only through the controller, which is offline."));
  left.append(h("h3", {}, "Signed revocation lists in force"),
    h("table", {}, h("caption", { class: "sr" }, "Revocation lists"),
      h("thead", {}, h("tr", {}, ["Issuer", "Seq", "Next update", "Status", "Revoked identities"].map((t) => h("th", { scope: "col" }, t)))),
      h("tbody", {}, srlRows)));

  const right = h("div", {});
  right.append(h("h3", {}, "Claims each unit holds (real attestations)"));
  for (const u of UNITS) {
    const rev = engine.u(u.id).status === "revoked";
    const card = h("div", { class: "unitcard" });
    card.append(h("h4", {}, glyphSvg(u), ` ${u.name}: ${u.role.replace(" (to be revoked)", "")}`, rev ? h("span", { class: "tag-rev" }, "IDENTITY REVOKED") : null));
    const rows = engine.claimsFor(u.id).map((c) =>
      h("tr", { class: rev ? "struck" : "" },
        h("td", { "data-label": "Claim" }, c.short),
        h("td", { "data-label": "Issuer" }, c.issuer),
        h("td", { "data-label": "Expires" }, `in ${c.expiresInDays} days`),
        h("td", { "data-label": "Data" }, c.dataText)));
    card.append(h("table", {}, h("caption", { class: "sr" }, `${u.name} claims`),
      h("thead", {}, h("tr", {}, ["Claim", "Issued by", "Expires", "Data"].map((t) => h("th", { scope: "col" }, t)))),
      h("tbody", {}, rows)));
    right.append(card);
  }
  right.append(h("p", { class: "attack-out" }, "Units 2 and 4 may send motion commands only to the unit named in their peer-motion claim, each other. Unit 3's names Unit 2 only. The intruder holds no claims at all."));
  wrap.append(left, right);
  root.replaceChildren(wrap);
}

// ----------------------------------------------------------- simulation loop
function clock() {
  $("#clock").textContent = `tick ${engine.tick} | t+${engine.now - T0 + (engine.tick ? TICK_SECS : 0)} s | ${engine.tick < SCRIPT_LENGTH ? `scripted run ${engine.tick}/${SCRIPT_LENGTH}` : "scripted run complete, fleet keeps operating"}`;
}

function doTick() {
  if (!engine) return;
  const t = engine.stepTick();
  placeUnits(false);
  controllerUi();
  t.records.forEach((r, i) => launch(r, i * 450));
  if (t.notes.length) {
    const el = $("#banner");
    el.className = "banner";
    el.textContent = t.notes.join(" ");
  }
  clock();
  refreshPolicy();
}

function schedule() {
  clearTimeout(tickTimer);
  if (!playing) return;
  tickTimer = setTimeout(() => {
    doTick();
    schedule();
  }, BASE_TICK_MS / speed);
}

function setPlaying(p) {
  playing = p;
  const b = $("#btn-play");
  b.textContent = p ? "Pause" : "Play";
  b.setAttribute("aria-pressed", String(p));
  schedule();
}

$("#btn-play").addEventListener("click", () => setPlaying(!playing));
$("#btn-step").addEventListener("click", () => {
  setPlaying(false);
  doTick();
});
$("#speed").addEventListener("change", (e) => {
  speed = Number(e.target.value);
  if (engine) placeUnits(false);
  schedule();
});
$("#btn-revoke").addEventListener("click", () => {
  const note = engine.revokeUnit3();
  if (note) {
    const el = $("#banner");
    el.className = "banner";
    el.textContent = note + (engine.pendingRevoke ? "" : " The next envelope from Unit 3 will be refused.");
    placeUnits(false);
    refreshPolicy();
  }
});
function controllerUi() {
  const off = engine ? engine.controllerOffline : false;
  const b = $("#btn-controller");
  b.setAttribute("aria-pressed", String(off));
  $("#ctl-state").classList.toggle("off", off);
  $("#ctl-state-text").textContent = off ? "Controller OFFLINE" : "Controller online";
}
$("#btn-controller").addEventListener("click", () => {
  if (!engine || busy) return;
  const notes = engine.setControllerOffline(!engine.controllerOffline);
  controllerUi();
  placeUnits(false);
  const el = $("#banner");
  el.className = "banner";
  el.textContent = notes.join(" ");
  refreshPolicy();
});
$("#chk-stale").addEventListener("change", (e) => {
  const recs = engine.setStale(e.target.checked);
  recs.forEach((r, i) => launch(r, i * 450));
  refreshPolicy();
});
$("#btn-restart").addEventListener("click", () => start());

// ------------------------------------------------------------------- layout
// On wide screens the envelope log can sit beside the fleet map at the map's height and scroll
// inside its own panel. The choice is remembered; with no saved choice it is on for very wide,
// ultrawide-shaped windows. The CSS only applies the layout from 1400 px up.
const LAYOUT_KEY = "atep-demo-log-side";
const layoutBtn = $("#btn-layout");
function savedLayout() { try { return localStorage.getItem(LAYOUT_KEY); } catch { return null; } }
function saveLayout(on) { try { localStorage.setItem(LAYOUT_KEY, on ? "1" : "0"); } catch { /* storage may be blocked */ } }
function syncMapHeight() {
  document.body.style.setProperty("--map-h", Math.round($("#map-panel").getBoundingClientRect().height) + "px");
}
function setLogSide(on, remember) {
  document.body.classList.toggle("log-side", on);
  layoutBtn.setAttribute("aria-pressed", String(on));
  if (remember) saveLayout(on);
  syncMapHeight();
}
if (typeof ResizeObserver !== "undefined") new ResizeObserver(syncMapHeight).observe($("#map-panel"));
const savedChoice = savedLayout();
setLogSide(savedChoice === null ? innerWidth >= 2200 && innerWidth / innerHeight >= 2 : savedChoice === "1", false);
layoutBtn.addEventListener("click", () => setLogSide(layoutBtn.getAttribute("aria-pressed") !== "true", true));

// -------------------------------------------------------------------- start
async function start() {
  setPlaying(false);
  busy = true;
  for (const f of flights) {
    f.g.remove();
    f.line.remove();
  }
  flights = [];
  selected = null;
  rowEls = new Map();
  logBody.replaceChildren();
  $("#inspect-out").replaceChildren();
  $("#inspect-sel").textContent = "Select an envelope in the log or click one in flight on the map.";
  $("#btn-decrypt").disabled = true;
  $("#btn-observer").disabled = true;
  $("#chk-stale").checked = false;
  $("#btn-controller").setAttribute("aria-pressed", "false");
  $("#ctl-state").classList.remove("off");
  $("#ctl-state-text").textContent = "Controller online";
  $("#attack-out").textContent = "Each attack is really attempted against the real verifier. Nothing here is mocked.";
  $("#log-count").textContent = "0";
  const banner0 = $("#banner");
  banner0.className = "banner";
  banner0.textContent = "Generating real identities, attestations and revocation lists (post-quantum keys take a moment)...";
  await new Promise((r) => setTimeout(r, 30));
  try {
    if (engine) engine.free();
    engine = await Engine.create();
  } catch (e) {
    banner0.className = "banner bad";
    banner0.textContent = "Could not start: " + (e && e.message ? e.message : e) + ". Serve this folder over http (node demo/serve.mjs); file:// cannot load WebAssembly modules.";
    return;
  }
  buildMap();
  placeUnits(true);
  policyKey = "";
  refreshPolicy(true);
  clock();
  busy = false;
  banner0.textContent = `Ready. Identities, attestations and SRLs generated in ${engine.setupMs} ms. Press Play (or Step) to run the scripted scenario.`;
}

const legend = $("#legend");
for (const p of [...UNITS, ATTACKER]) legend.append(h("li", {}, glyphSvg(p), `${p.n ? p.n + " " : ""}${p.role}`));
legend.append(h("li", {}, "Dashed lines: encrypted envelopes in flight. X marks: commanded waypoints."));

start();
window.__atepDemo = { get engine() { return engine; } };
